$ npm install @supabase/supabase-js

import { createClient } from '@supabase/supabase-js'

const supabase = createClient(
  process.env.SUPABASE_URL!,
  process.env.SUPABASE_ANON_KEY!
)

// SELECT
const { data, error } = await supabase
  .from('tabla')
  .select('*')
  .eq('columna', valor)

// INSERT
await supabase.from('tabla').insert({ campo: 'valor' })

// UPDATE
await supabase.from('tabla').update({ campo: 'nuevo' }).eq('id', 1)

// DELETE
await supabase.from('tabla').delete().eq('id', 1)

// Registro
await supabase.auth.signUp({ email, password })

// Login
await supabase.auth.signInWithPassword({ email, password })

// Sesión actual
const { data: { session } } = await supabase.auth.getSession()

// Logout
await supabase.auth.signOut()

// Subir archivo
await supabase.storage.from('bucket').upload('ruta/archivo.png', file)

// Obtener URL pública
const { data } = supabase.storage.from('bucket').getPublicUrl('ruta/archivo.png')

// Descargar
await supabase.storage.from('bucket').download('ruta/archivo.png')

-- Habilitar RLS en la tabla
ALTER TABLE tabla ENABLE ROW LEVEL SECURITY;

-- Permitir SELECT solo al dueño del registro
CREATE POLICY "select_own" ON tabla
  FOR SELECT USING (auth.uid() = user_id);

-- Permitir INSERT autenticado
CREATE POLICY "insert_auth" ON tabla
  FOR INSERT WITH CHECK (auth.uid() = user_id);
